                            professions: ['培育中心', 'A区 - 阿卡迪亚', 'B区 - 巴别', 'C区 - 公司镇']
                        }
                    },
                    features: {
                        人种: ['东亚', '南亚', '西亚', '北亚', '中亚', '东南亚', '南美洲', '北美洲', '欧洲', '非洲', '大洋洲', '混血'],
                        肤色: ['浅棕', '深棕', '浅黑', '深黑', '浅白', '深白', '古铜', '麦色', '奶油色', '混血'],
                        核心人格类型: {
                            '猎人': ['专业冷静型', '淫荡放纵型', '暴虐玩弄型', '温柔背叛型'],
                            '肉畜': ['顺从矛盾型', '反抗脆弱型', '主动淫乱型', '恐惧愉悦型']
                        },
                        身高: ['185cm以上', '175-184cm', '165-174cm', '165cm以下'],
                        胸围: ['丰满饱满（D罩杯）', '匀称适中（C罩杯）', '相对娇小（B罩杯）', '平坦（VV）'],
                        臀围: ['圆润挺翘', '标准匀称', '稍显扁平', '丰满多肉'],
                    },
                },
            },
        };

        const bodyDetailsData = {
            '肉棒长度': {
                '男': ['25cm', '18cm', '13cm', '10cm'],
            },
            '小穴': {
                '女': ['紧致一线天', '美鲍嫩穴', '紧致多褶', '普通肉穴'],
            },
            '菊穴': {
                '女': ['粉嫩雏菊', '紧致后庭', '开发适度', '普通菊穴'],
                '男': ['粉嫩雏菊', '紧致后庭', '开发适度', '普通菊穴'],
            }
        };

        // 选择存储和顺序控制
        const selections = {};
        const selectionOrder = [
            'status',
            'meatAnimalType',
            'gender',
            'profession',
            'companyAction',
            'feature',
            'bodyDetails',
            'appearance',
            'customScene',
        ];

        function getRandomElement(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
        function navigateTo(screenId) {
            document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
            const el = document.getElementById(screenId);
            if (el) el.classList.add('active');
        }

        function renderCardOptions(containerId, options, type) {
            const container = document.getElementById(containerId);
            container.innerHTML = '';
            const grid = document.createElement('div');
            grid.className = 'selection-grid';

            if (type === 'gender' && selections.status === '肉畜') {
                const cardMale = createCard(type, '男');
                cardMale.querySelector('h3').textContent = '雄畜';
                grid.appendChild(cardMale);

                const cardFemale = createCard(type, '女');
                cardFemale.querySelector('h3').textContent = '雌畜';
                grid.appendChild(cardFemale);
            } else if (type === 'gender' && Array.isArray(options)) {
                options.forEach(opt => {
                    let desc = '';
                    if (opt === '男') desc = '';
                    else if (opt === '女') desc = '';
                    grid.appendChild(createCard(type, opt, desc));
                });
            } else if (Array.isArray(options)) {
                options.forEach(opt => grid.appendChild(createCard(type, opt, '')));
            } else {
                for (const [key, value] of Object.entries(options)) {
                    let desc = '';
                    if (value && typeof value === 'object' && value.professions) {
                        desc = `可选职位：${value.professions.slice(0,2).join('、')}`;
                    }
                    grid.appendChild(createCard(type, key, desc));
                }
            }
            container.appendChild(grid);

            // 启用/禁用下一步按钮
            const nextButton = container.closest('.screen')?.querySelector('.btn-primary');
            if (nextButton) {
                nextButton.disabled = !selections[type];
            }
        }

        function createCard(type, value, description) {
            const el = document.createElement('div');
            el.className = 'card';
            el.dataset.type = type;
            el.dataset.value = value;
            if (selections[type] === value) el.classList.add('selected');
            const title = document.createElement('h3');
            title.textContent = value;
            el.appendChild(title);
            if (description) {
                const p = document.createElement('p');
                p.textContent = description;
                el.appendChild(p);
            }
            return el;
        }

        // 身体特征渲染
        function renderFeaturesScreen() {
            const container = document.getElementById('features-container');
            container.innerHTML = '';
            selections.feature = selections.feature || {};
            const featureSet = data.gender[selections.gender].features;
            for (const category in featureSet) {
                const categoryDiv = document.createElement('div');
                categoryDiv.className = 'feature-category';
                const title = document.createElement('h4');
                title.textContent = category;
                categoryDiv.appendChild(title);
                const optionsGrid = document.createElement('div');
                optionsGrid.className = 'feature-options-grid';

                const rawOptions = featureSet[category];
                let levels = [];
                if (Array.isArray(rawOptions)) {
                    levels = rawOptions;
                } else if (rawOptions && typeof rawOptions === 'object') {
                    const statusKey = selections.status;
                    if (statusKey && Array.isArray(rawOptions[statusKey])) {
                        levels = rawOptions[statusKey];
                    } else if (Array.isArray(rawOptions.default)) {
                        levels = rawOptions.default;
                    } else {
                        levels = Object.values(rawOptions).reduce((acc, item) => {
                            if (Array.isArray(item)) acc.push(...item);
                            return acc;
                        }, []);
                    }
                }

                levels.forEach(level => {
                    const optionDiv = document.createElement('div');
                    optionDiv.className = 'feature-option';
                    optionDiv.dataset.category = category;
                    optionDiv.dataset.value = level;
                    optionDiv.textContent = level;
                    optionsGrid.appendChild(optionDiv);
                });
                categoryDiv.appendChild(optionsGrid);
                container.appendChild(categoryDiv);

                // 恢复之前的选择
                if (selections.feature[category]) {
                    const sel = optionsGrid.querySelector(`[data-value="${selections.feature[category]}"]`);
                    if (sel) sel.classList.add('selected');
                }
            }
            checkAllFeaturesSelected();
        }

        function renderBodyDetailsScreen() {
            const container = document.getElementById('body-details-container');
            container.innerHTML = '';
            selections.bodyDetails = selections.bodyDetails || {};
            const gender = selections.gender;
            const status = selections.status;

            const categoriesToShow = {
                '肉棒长度': bodyDetailsData['肉棒长度'] ? bodyDetailsData['肉棒长度'][gender] : undefined,
                '小穴': bodyDetailsData['小穴'] ? bodyDetailsData['小穴'][gender] : undefined,
                '菊穴': (gender === '女' || (gender === '男' && status === '肉畜')) ? (bodyDetailsData['菊穴'] ? bodyDetailsData['菊穴'][gender] : undefined) : undefined
            };

            for (const categoryName in categoriesToShow) {
                const options = categoriesToShow[categoryName];
                if (options) {
                    const categoryDiv = document.createElement('div');
                    categoryDiv.className = 'feature-category';

                    const title = document.createElement('h4');
                    title.textContent = categoryName;
                    categoryDiv.appendChild(title);

                    const optionsGrid = document.createElement('div');
                    optionsGrid.className = 'feature-options-grid';

                    options.forEach(optionValue => {
                        const optionDiv = document.createElement('div');
                        optionDiv.className = 'feature-option';
                        optionDiv.dataset.category = categoryName;
                        optionDiv.dataset.value = optionValue;
                        optionDiv.textContent = optionValue;
                        optionsGrid.appendChild(optionDiv);
                    });

                    categoryDiv.appendChild(optionsGrid);
                    container.appendChild(categoryDiv);

                    // Restore selection
                    if (selections.bodyDetails[categoryName]) {
                        const sel = optionsGrid.querySelector(`[data-value="${selections.bodyDetails[categoryName]}"]`);
                        if (sel) sel.classList.add('selected');
                    }
                }
            }
            checkBodyDetailsSelected();
        }

        function renderAppearanceScreen() {
            selections.appearance = selections.appearance || {};

            // --- 1. Render Hair Length ---
            const hairLengthContainer = document.getElementById('hairstyle-container');
            hairLengthContainer.innerHTML = '';
            const hairLengthTitle = document.createElement('h4');
            hairLengthTitle.textContent = "头发长度";
            hairLengthContainer.appendChild(hairLengthTitle);

            const hairLengthGrid = document.createElement('div');
            hairLengthGrid.className = 'feature-options-grid';
            const hairLengthOptions = selections.gender === '男' 
                ? ['短发', '齐肩'] 
                : ['短发', '齐肩', '过肩', '齐腰', '到脚踝'];

            if (selections.appearance.hairLength && !hairLengthOptions.includes(selections.appearance.hairLength)) {
                delete selections.appearance.hairLength;
            }

            hairLengthOptions.forEach(style => {
                const optionDiv = document.createElement('div');
                optionDiv.className = 'feature-option';
                optionDiv.dataset.category = 'hairLength';
                optionDiv.dataset.value = style;
                optionDiv.textContent = style;
                if (selections.appearance.hairLength === style) {
                    optionDiv.classList.add('selected');
                }
                hairLengthGrid.appendChild(optionDiv);
            });
            hairLengthContainer.appendChild(hairLengthGrid);

            // --- 2. Render Hair Style ---
            const hairStyleContainer = document.getElementById('hairstyle-proper-container');
            hairStyleContainer.innerHTML = '';
            const hairStyleTitle = document.createElement('h4');
            hairStyleTitle.textContent = "发型";
            hairStyleContainer.appendChild(hairStyleTitle);

            const hairStyleGrid = document.createElement('div');
            hairStyleGrid.className = 'feature-options-grid';
            const hairStyleOptions = selections.gender === '男' 
                ? ['寸头', '背头'] 
                : ['单马尾', '双马尾', '披散', '侧马尾'];

            const isCustomHairStyle = selections.appearance.hairStyle && !hairStyleOptions.includes(selections.appearance.hairStyle);

            if (selections.appearance.hairStyle && !isCustomHairStyle && !hairStyleOptions.includes(selections.appearance.hairStyle)) {
                 delete selections.appearance.hairStyle;
            }

            hairStyleOptions.forEach(style => {
                const optionDiv = document.createElement('div');
                optionDiv.className = 'feature-option';
                optionDiv.dataset.category = 'hairStyle';
                optionDiv.dataset.value = style;
                optionDiv.textContent = style;
                if (selections.appearance.hairStyle === style) {
                    optionDiv.classList.add('selected');
                }
                hairStyleGrid.appendChild(optionDiv);
            });
            hairStyleContainer.appendChild(hairStyleGrid);

            // --- 3. Restore Input Values ---
            $('#hair-color-input').val(selections.appearance.hairColor || '');
            $('#eye-color-input').val(selections.appearance.eyeColor || '');
            $('#custom-hairstyle-input').val(isCustomHairStyle ? selections.appearance.hairStyle : '');
            $('#hair-accessory-input').val(selections.appearance.hairAccessory || '');
            $('#other-accessory-input').val(selections.appearance.otherAccessory || '');

            checkAppearanceSelected();
        }

        function checkAllFeaturesSelected() {
            const featureSet = data.gender[selections.gender]?.features || {};
            const allSelected = Object.keys(featureSet).every(cat => selections.feature && selections.feature[cat]);
            document.getElementById('to-body-details').disabled = !allSelected;
        }

        function checkBodyDetailsSelected() {
            const gender = selections.gender;
            const status = selections.status;
            const requiredCategories = [];
            if (bodyDetailsData['肉棒长度'] && bodyDetailsData['肉棒长度'][gender]) requiredCategories.push('肉棒长度');
            if (bodyDetailsData['小穴'] && bodyDetailsData['小穴'][gender]) requiredCategories.push('小穴');

            if (bodyDetailsData['菊穴'] && bodyDetailsData['菊穴'][gender]) {
                if (gender === '女' || (gender === '男' && status === '肉畜')) {
                    requiredCategories.push('菊穴');
                }
            }

            const allSelected = requiredCategories.every(cat => selections.bodyDetails && selections.bodyDetails[cat]);
            document.getElementById('to-appearance').disabled = !allSelected;
        }

        function checkAppearanceSelected() {
            const hairLength = selections.appearance?.hairLength || '';
            const hairStyle = selections.appearance?.hairStyle || '';
            const allSelected = hairLength.trim() !== '' && hairStyle.trim() !== '';
            document.getElementById('to-summary').disabled = !allSelected;
        }

        function handleRandomize(screenId) {
            const screenElement = document.getElementById(screenId);
            if (!screenElement) return;
            switch (screenId) {
                case 'screen-gender':
                    const genderCards = screenElement.querySelectorAll('.card:not(.disabled)');
                    if (genderCards.length > 0) getRandomElement(Array.from(genderCards)).click();
                    break;
                case 'screen-status':
                    const statusCards = screenElement.querySelectorAll('.card:not(.disabled)');
                    if (statusCards.length > 0) getRandomElement(Array.from(statusCards)).click();
                    break;
                case 'screen-profession':
                    delete selections.profession;
                    const profCards = screenElement.querySelectorAll('.card:not(.disabled)');
                    if (profCards.length > 0) getRandomElement(Array.from(profCards)).click();
                    break;
                case 'screen-features':
                    const personalityInput = document.getElementById('custom-personality-input');
                    const featuresInput = document.getElementById('custom-features-input');
                    if (personalityInput) personalityInput.value = '';
                    if (featuresInput) featuresInput.value = '';
                    delete selections.customPersonality;
                    delete selections.customFeature;
                    screenElement.querySelectorAll('.feature-category').forEach(cat => {
                        const opts = cat.querySelectorAll('.feature-option:not(.disabled)');
                        if (opts.length > 0) getRandomElement(Array.from(opts)).click();
                    });
                    break;
            }
        }

        function updateSelection(type, value) {
            if (selections[type] === value) return;
            selections[type] = value;
            const currentIndex = selectionOrder.indexOf(type);
            for (let i = currentIndex + 1; i < selectionOrder.length; i++) {
                const key = selectionOrder[i];
                delete selections[key];
                const el = document.getElementById(`custom-${key}-input`);
                if (el) el.value = '';
            }
        }

        // 事件委托处理点击
        document.body.addEventListener('click', function (e) {
            const card = e.target.closest('.card');
            const featureOption = e.target.closest('.feature-option');
            const backBtn = e.target.closest('.back-btn');
            const randomizeBtn = e.target.closest('.randomize-btn');
            const nextBtn = e.target.closest('.btn-primary');

            if (randomizeBtn) {
                handleRandomize(randomizeBtn.dataset.screenId);
                return;
            }

            if (card) {
                const type = card.dataset.type;
                const value = card.dataset.value;

                updateSelection(type, value);

                // 视觉标记选中状态
                const container = card.parentElement;
                if (container) container.querySelectorAll('.card').forEach(c => c.classList.remove('selected'));
                card.classList.add('selected');

                // 启用当前屏幕的下一步按钮
                const btn = card.closest('.screen').querySelector('.btn-primary');
                if (btn) btn.disabled = false;
            }

            if (featureOption && !featureOption.classList.contains('disabled')) {
                const category = featureOption.dataset.category;
                const value = featureOption.dataset.value;

                const bodyDetailCategories = ['肉棒长度', '小穴', '菊穴'];
                const appearanceCategories = ['hairLength', 'hairStyle'];

                if (bodyDetailCategories.includes(category)) {
                    selections.bodyDetails = selections.bodyDetails || {};
                    selections.bodyDetails[category] = value;
                    checkBodyDetailsSelected();
                } else if (appearanceCategories.includes(category)) {
                    selections.appearance = selections.appearance || {};
                    selections.appearance[category] = value;
                    if (category === 'hairStyle') {
                        document.getElementById('custom-hairstyle-input').value = '';
                    }
                    checkAppearanceSelected();
                } else {
                    selections.feature = selections.feature || {};
                    selections.feature[category] = value;
                    checkAllFeaturesSelected();
                }
                featureOption.parentElement.querySelectorAll('.feature-option').forEach(opt => opt.classList.remove('selected'));
                featureOption.classList.add('selected');
            }

            if (backBtn) {
                navigateTo(backBtn.dataset.target);
            }
            if (nextBtn && !nextBtn.disabled) {
                handleNext(nextBtn.id);
            }
        });

        document.getElementById('custom-personality-input')?.addEventListener('input', e => {
            selections.customPersonality = e.target.value.trim();
        });

        document.getElementById('custom-features-input')?.addEventListener('input', e => {
            selections.customFeature = e.target.value.trim();
        });

        document.getElementById('hair-color-input')?.addEventListener('input', e => {
            selections.appearance = selections.appearance || {};
            selections.appearance.hairColor = e.target.value.trim();
            checkAppearanceSelected();
        });
        document.getElementById('eye-color-input')?.addEventListener('input', e => {
            selections.appearance = selections.appearance || {};
            selections.appearance.eyeColor = e.target.value.trim();
        });
        document.getElementById('custom-hairstyle-input')?.addEventListener('input', e => {
            selections.appearance = selections.appearance || {};
            const value = e.target.value.trim();
            if (value) {
                selections.appearance.hairStyle = value;
                document.querySelectorAll('#hairstyle-proper-container .feature-option').forEach(opt => opt.classList.remove('selected'));
            } else {
                delete selections.appearance.hairStyle;
            }
            checkAppearanceSelected();
        });
        document.getElementById('hair-accessory-input')?.addEventListener('input', e => {
            selections.appearance = selections.appearance || {};
            selections.appearance.hairAccessory = e.target.value.trim();
        });
        document.getElementById('other-accessory-input')?.addEventListener('input', e => {
            selections.appearance = selections.appearance || {};
            selections.appearance.otherAccessory = e.target.value.trim();
        });

        document.getElementById('custom-scene-input').addEventListener('input', e => {
            selections.customScene = e.target.value.trim();
        });

        // 下一步处理函数
        function handleNext(nextBtnId) {
            switch (nextBtnId) {
                case 'to-next-from-status':
                    if (selections.status === '肉畜') {
                        navigateTo('screen-meat-animal-type');
                    } else {
                        renderCardOptions('gender-options', Object.keys(data.gender), 'gender');
                        $('#screen-gender .back-btn').attr('data-target', 'screen-status');
                        navigateTo('screen-gender');
                    }
                    break;

                case 'to-gender':
                    renderCardOptions('gender-options', Object.keys(data.gender), 'gender');
                    $('#screen-gender .back-btn').attr('data-target', 'screen-meat-animal-type');
                    navigateTo('screen-gender');
                    break;

                case 'to-profession':
                    const genderKey = selections.gender;
                    const statusObj = data.gender[genderKey].status[selections.status];
                    if (statusObj && statusObj.professions) {
                        renderCardOptions('profession-options', statusObj.professions, 'profession');
                    } else {
                        renderCardOptions('profession-options', [], 'profession');
                    }
                    $('#screen-profession .back-btn').attr('data-target', 'screen-gender');
                    navigateTo('screen-profession');
                    break;

                case 'to-features':
                    if (selections.profession === 'C区 - 公司镇') {
                        const actionOptions = selections.status === '肉畜'
                            ? ['签署自愿培训协议']
                            : ['准备入会事宜', '开始狩猎'];
                        renderCardOptions('company-action-options', actionOptions, 'companyAction');
                        navigateTo('screen-company-action');
                    } else {
                        renderFeaturesScreen();
                        $('#screen-features .back-btn').attr('data-target', 'screen-profession');
                        navigateTo('screen-features');
                    }
                    break;

                case 'to-body-details':
                    renderBodyDetailsScreen();
                    navigateTo('screen-body-details');
                    break;

                case 'to-features-from-action':
                    renderFeaturesScreen();
                    $('#screen-features .back-btn').attr('data-target', 'screen-company-action');
                    navigateTo('screen-features');
                    break;

                case 'to-appearance':
                    renderAppearanceScreen();
                    navigateTo('screen-appearance');
                    break;

                case 'to-summary':
                    buildSummary();
                    navigateTo('screen-summary');
                    break;

                case 'confirm-and-start':
                    let finalString = `{{user}}个人信息：身份是${selections.status}，`;
                    if (selections.meatAnimalType) {
                        finalString += `肉畜类型是${selections.meatAnimalType}，`;
                    }

                    let genderDisplay = selections.gender;
                    if (selections.status === '肉畜') {
                        if (genderDisplay === '男') genderDisplay = '雄畜';
                        else if (genderDisplay === '女') genderDisplay = '雌畜';
                    }
                    finalString += `性别：${genderDisplay}，`;

                    if (selections.profession) finalString += `现在位于${selections.profession}。`;
                    if (selections.companyAction) finalString += ` 当前行动：${selections.companyAction}。`;
                    if (selections.feature) {
                        const fdesc = Object.entries(selections.feature).map(([k,v]) => `${k}：${v}`).join('，');
                        finalString += ` 身体属性为 ${fdesc}。`;
                    }
                    if (selections.bodyDetails) {
                        const bdesc = Object.entries(selections.bodyDetails).map(([k,v]) => `${k}为${v}`).join('，');
                        if (bdesc) finalString += ` 身体细节为 ${bdesc}。`;
                    }

                    let aiToGenerateList = [];
                    if (selections.appearance) {
                        const { hairColor, eyeColor, hairLength, hairStyle, hairAccessory, otherAccessory } = selections.appearance;
                        let appearanceDesc = [];

                        if (hairColor) {
                            appearanceDesc.push(`发色为${hairColor}`);
                        } else {
                            aiToGenerateList.push('发色');
                        }

                        if (eyeColor) {
                            appearanceDesc.push(`瞳色为${eyeColor}`);
                        } else {
                            aiToGenerateList.push('瞳色');
                        }

                        if (hairLength) appearanceDesc.push(`头发长度为${hairLength}`);
                        if (hairStyle) appearanceDesc.push(`发型为${hairStyle}`);

                        if (appearanceDesc.length > 0) finalString += ` 外貌方面，${appearanceDesc.join('，')}。`;
                        if (hairAccessory) finalString += ` 头发上装饰着${hairAccessory}。`;
                        if (otherAccessory) finalString += ` 此外还有${otherAccessory}的配饰。`;
                    }
                    if (selections.customPersonality) finalString += ` 补充人格特征：${selections.customPersonality}。`;
                    if (selections.customFeature) finalString += ` 补充身体特征：${selections.customFeature}。`;

                    if (selections.customScene) finalString += ` 自定义开场：${selections.customScene}；`;

                    let finalInstruction = '请根据世界观，生成符合人物身份与设定的开局';
                    if (aiToGenerateList.length > 0) {
                        finalInstruction += `，并补充生成角色的${aiToGenerateList.join('和')}`;
                    }
                    finalInstruction += '。';
                    finalString += finalInstruction;

                    console.log(finalString);

                    // 发送锁（防止重复触发多次发送）
                    if (!window.__sending_profile) window.__sending_profile = false;

                    if (window.__sending_profile) {
                        return;
                    }
                    window.__sending_profile = true;

                    try {
                        if (typeof triggerSlash === 'function') {
                            try {
                                triggerSlash(`/send ${finalString}|/trigger`);
                            } catch (err) {
                                console.error('triggerSlash 调用失败：', err);
                            }
                        }

                        // 显示已注入界面
                        const finalDiv = document.createElement('div');
                        finalDiv.style.padding = '20px';
                        finalDiv.style.textAlign = 'center';
                        const finalTitle = document.createElement('h2');
                        finalTitle.className = 'screen-header';
                        finalTitle.style.cssText = 'margin-bottom:1rem;border:none;';
                        finalTitle.textContent = '档案已发送';
                        const finalText = document.createElement('p');
                        finalText.style.color = 'var(--accent-color)';
                        finalText.style.fontSize = '1.05rem';
                        finalText.textContent = '[档案已生成并注入聊天栏...]';
                        finalDiv.appendChild(finalTitle);
                        finalDiv.appendChild(finalText);
                        document.querySelector('.generator-container').innerHTML = '';
                        document.querySelector('.generator-container').appendChild(finalDiv);

                    } finally {
                        setTimeout(() => { window.__sending_profile = false; }, 500);
                    }
                    break;
            }
        }

        function buildSummary() {
            const summaryContainer = document.getElementById('summary-content');
            summaryContainer.innerHTML = '';
            summaryContainer.className = 'summary-section';
            const fields = {
                身份: 'status',
                肉畜类型: 'meatAnimalType',
                性别: 'gender',
                所在地: 'profession',
            };
            for (const [label, key] of Object.entries(fields)) {
                if (selections[key]) {
                    let displayValue = selections[key];
                    if (key === 'gender' && selections.status === '肉畜') {
                        if (displayValue === '男') displayValue = '雄畜';
                        else if (displayValue === '女') displayValue = '雌畜';
                    }
                    const item = document.createElement('div');
                    item.className = 'summary-item';
                    item.innerHTML = `<span class="summary-label">${label}</span><span class="summary-value">${displayValue}</span>`;
                    summaryContainer.appendChild(item);
                }
            }
            if (selections.companyAction) {
                const item = document.createElement('div');
                item.className = 'summary-item';
                item.innerHTML = `<span class="summary-label">当前行动</span><span class="summary-value">${selections.companyAction}</span>`;
                summaryContainer.appendChild(item);
            }
            if (selections.feature) {
                for (const [cat, lvl] of Object.entries(selections.feature)) {
                    const item = document.createElement('div');
                    item.className = 'summary-item';
                    item.innerHTML = `<span class="summary-label">${cat}</span><span class="summary-value">${lvl}</span>`;
                    summaryContainer.appendChild(item);
                }
            }
            if (selections.bodyDetails) {
                for (const [cat, lvl] of Object.entries(selections.bodyDetails)) {
                    if (lvl) {
                        const item = document.createElement('div');
                        item.className = 'summary-item';
                        item.innerHTML = `<span class="summary-label">${cat}</span><span class="summary-value">${lvl}</span>`;
                        summaryContainer.appendChild(item);
                    }
                }
            }
            if (selections.appearance) {
                const appearanceFields = {
                    '发色': 'hairColor',
                    '瞳色': 'eyeColor',
                    '头发长度': 'hairLength',
                    '发型': 'hairStyle',
                    '头发配饰': 'hairAccessory',
                    '其他配饰': 'otherAccessory'
                };
                for (const [label, key] of Object.entries(appearanceFields)) {
                    if (selections.appearance[key]) {
                        const item = document.createElement('div');
                        item.className = 'summary-item';
                        item.innerHTML = `<span class="summary-label">${label}</span><span class="summary-value">${selections.appearance[key]}</span>`;
                        summaryContainer.appendChild(item);
                    }
                }
            }
            if (selections.customPersonality) {
                const item = document.createElement('div');
                item.className = 'summary-item';
                item.innerHTML = `<span class="summary-label">补充人格特征</span><span class="summary-value">${selections.customPersonality}</span>`;
                summaryContainer.appendChild(item);
            }
            if (selections.customFeature) {
                const item = document.createElement('div');
                item.className = 'summary-item';
                item.innerHTML = `<span class="summary-label">补充身体特征</span><span class="summary-value">${selections.customFeature}</span>`;
                summaryContainer.appendChild(item);
            }
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            // 启用身份选择
            document.querySelectorAll('#screen-status .card').forEach(card => {
                card.addEventListener('click', () => {
                    document.getElementById('to-next-from-status').disabled = false;
                });
            });

            // 绑定下一步按钮事件
            const mapping = [
                'to-next-from-status',
                'to-gender',
                'to-profession',
                'to-features',
                'to-body-details',
                'to-features-from-action',
                'to-appearance',
                'to-summary',
                'confirm-and-start'
            ];
            mapping.forEach(id => {
                const el = document.getElementById(id);
                if (el) el.addEventListener('click', () => {
                    if (!el.disabled) handleNext(id);
                });
            });

            // 随机选择按钮
            document.querySelectorAll('.randomize-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    handleRandomize(btn.dataset.screenId);
                    e.stopPropagation();
                });
            });

            // 确保特征选择完成前禁用下一步
            document.getElementById('to-body-details').disabled = true;
        });
    </script>
</body>
</html>
